cat > masked.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
API_TOKEN="sk-live-9f2a-DO-NOT-LEAK"
mask() { sed "s|${API_TOKEN}|***|g"; }
{
  set -x
  curl -s -o /dev/null "https://example.com/deploy?token=$API_TOKEN" || true
  set +x
} 2>&1 | mask
EOF
chmod +x masked.sh && ./masked.sh

import { createClient } from "@1claw/sdk";

async function main() {
  const client = createClient({
    baseUrl: "https://api.1claw.co",
    apiKey: process.env.ONECLAW_API_KEY,
  });

  const res = await client.secrets.get(process.env.ONECLAW_VAULT_ID!, "api-keys/openai");
  if (res.error) {
    console.error(res.error.message);
  } else {
    console.log(res.data.value);
  }
}

main();
